options(keep.source=FALSE)
a<-list(1L);class(a)<-"foo";names(a)<-NA_character_
b<-list(1L);names(b)<-NA_character_;class(b)<-"foo"
cat("CLASSED_NA\n")
list(a)
cat("ORDER_NA\n")
c(identical(a,b),identical(a,b,attrib.as.set=FALSE))
f<-function()0L;g<-f;attr(f,"payload")<-a;attr(g,"payload")<-b
cat("CLOSURE_NA\n")
c(identical(f,g),identical(f,g,attrib.as.set=FALSE))
a<-list();class(a)<-"foo";names(a)<-character()
b<-list();names(b)<-character();class(b)<-"foo"
cat("CLASSED_EMPTY\n")
list(a)
cat("ORDER_EMPTY\n")
c(identical(a,b),identical(a,b,attrib.as.set=FALSE))
attr(f,"payload")<-a;attr(g,"payload")<-b
cat("CLOSURE_EMPTY\n")
c(identical(f,g),identical(f,g,attrib.as.set=FALSE))
u<-list(1L);names(u)<-NA_character_
cat("UNCLASSED_NA\n")
list(u)
a<-list(a=1L);class(a)<-"foo";names(a)<-NULL
b<-list(1L);class(b)<-"foo"
cat("CLASS_ONLY\n")
c(identical(a,b),identical(a,b,attrib.as.set=FALSE))
cat("DONE\n")
